/* Make the div a flex container */
display: flex;

/* Or, for inline flex */
display: inline-flex;

/* This will apply flexbox properties to the direct children */
.container {
  display: flex;
}

/* Flex container */
.container {
  display: flex;
}

/* Flex items */
.item {
  width: 100px;
  height: 50px;
  background-color: lightblue;
}

/* Change main axis to column */
.container {
  display: flex;
  flex-direction: column;
}

/* Items will now stack vertically */

/* Flex items */
.item {
  flex-grow: 1;
  width: 100px;
}

/* All items will grow equally to fill available space */

/* Flex items */
.item {
  flex-shrink: 1;
  width: 200px;
}

/* Items will shrink if the container is too small */

/* Flex items */
.item {
  flex-basis: 100px;
}

/* Items will initially be 100px wide */

/* Flex container */
.container {
  display: flex;
  align-items: center;
  height: 200px;
}

/* Items will be vertically centered */

/* Flex container */
.container {
  display: flex;
  flex-wrap: wrap;
}

